#include "cloudmoon_ws_tls.h"
#include "cloudmoon_upgrade.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CM_WS_HTTP_HEADER_MAX 16384U
#define CM_WS_FRAME_MAX 32768U
#define CM_WS_PENDING_MAX 1024U
struct cm_ws_tls_transport { cm_tls_connection *tls; uint8_t pending[CM_WS_PENDING_MAX]; size_t pending_length; };
static int cm_find_header_end(const uint8_t*d,size_t n,size_t*end){size_t i;if(!d||!end||n<4)return 0;for(i=0;i+3<n;i++)if(d[i]=='\r'&&d[i+1]=='\n'&&d[i+2]=='\r'&&d[i+3]=='\n'){*end=i+4;return 1;}return 0;}
static int cm_read_exact(cm_ws_tls_transport*t,uint8_t*out,size_t n){size_t copied=0;if(!t||(!out&&n))return -1;if(t->pending_length){size_t z=t->pending_length<n?t->pending_length:n;memcpy(out,t->pending,z);memmove(t->pending,t->pending+z,t->pending_length-z);t->pending_length-=z;copied=z;}while(copied<n){int z=cm_tls_read_polarssl(t->tls,out+copied,n-copied);if(z<=0)return -1;copied+=(size_t)z;}return 0;}
int cm_ws_tls_connect(cm_ws_tls_transport**out,const char*hostname,uint16_t port,const char*path,const char*ca,unsigned timeout,cm_random_source_fn rng,void*ctx){cm_ws_tls_transport*t=NULL;uint8_t nonce[16],incoming[1024],response[CM_WS_HTTP_HEADER_MAX];char host[320],request[2048],key[25];size_t response_len=0,header_end=0;int req_len;if(!out||!hostname||!*hostname||!port||!path||path[0]!='/'||!ca||!rng)return -1;*out=NULL;if(port==443){if(snprintf(host,sizeof(host),"%s",hostname)>=(int)sizeof(host))return -1;}else if(snprintf(host,sizeof(host),"%s:%u",hostname,(unsigned)port)>=(int)sizeof(host))return -1;t=(cm_ws_tls_transport*)calloc(1,sizeof(*t));if(!t)return -1;if(cm_tls_connect_polarssl(&t->tls,hostname,port,ca,timeout)!=0)goto fail;if(cm_random_bytes(rng,ctx,nonce,sizeof(nonce))!=0)goto fail;req_len=cm_ws_build_upgrade_request(request,sizeof(request),host,path,nonce,key);if(req_len<=0||cm_tls_write_polarssl(t->tls,request,(size_t)req_len)!=req_len)goto fail;while(!cm_find_header_end(response,response_len,&header_end)){int n;if(response_len>=sizeof(response))goto fail;n=cm_tls_read_polarssl(t->tls,incoming,sizeof(incoming));if(n<=0||(size_t)n>sizeof(response)-response_len)goto fail;memcpy(response+response_len,incoming,(size_t)n);response_len+=(size_t)n;}if(cm_ws_validate_upgrade_response((const char*)response,header_end,key)!=0)goto fail;if(response_len>header_end){size_t extra=response_len-header_end;if(extra>sizeof(t->pending))goto fail;memcpy(t->pending,response+header_end,extra);t->pending_length=extra;}*out=t;return 0;fail:if(t){if(t->tls)cm_tls_close_polarssl(t->tls);free(t);}return -1;}
int cm_ws_tls_send(cm_ws_tls_transport*t,uint8_t opcode,int fin,const void*payload,size_t len,cm_random_source_fn rng,void*ctx){uint8_t frame[CM_WS_FRAME_MAX+14],mask[4];int n;if(!t||!t->tls||!rng||len>CM_WS_FRAME_MAX)return -1;if(cm_random_bytes(rng,ctx,mask,sizeof(mask))!=0)return -1;n=cm_ws_encode_client_frame(frame,sizeof(frame),opcode,fin,(const uint8_t*)payload,len,mask);if(n<0)return -1;return cm_tls_write_polarssl(t->tls,frame,(size_t)n)==n?n:-1;}
int cm_ws_tls_read_frame(cm_ws_tls_transport*t,cm_ws_frame_info_t*info,void*payload,size_t cap){uint8_t frame[CM_WS_FRAME_MAX+14],first[2],ext[8];uint64_t len;size_t h=2,total;int decoded;if(!t||!t->tls||!info||(!payload&&cap))return -1;if(cm_read_exact(t,first,2)!=0||(first[1]&0x80))return -1;if((first[1]&127)<126)len=first[1]&127;else if((first[1]&127)==126){if(cm_read_exact(t,ext,2)!=0)return -1;len=((uint64_t)ext[0]<<8)|ext[1];if(len<126)return -1;memcpy(frame+2,ext,2);h=4;}else{size_t i;if(cm_read_exact(t,ext,8)!=0||(ext[0]&0x80))return -1;len=0;for(i=0;i<8;i++)len=(len<<8)|ext[i];if(len<=65535)return -1;memcpy(frame+2,ext,8);h=10;}if(len>CM_WS_FRAME_MAX||len>cap||len>(uint64_t)(sizeof(frame)-h))return -1;frame[0]=first[0];frame[1]=first[1];total=h+(size_t)len;if(cm_read_exact(t,frame+h,(size_t)len)!=0)return -1;decoded=cm_ws_decode_server_frame(frame,total,info,(uint8_t*)payload,cap);return decoded<0?-1:decoded;}
void cm_ws_tls_close(cm_ws_tls_transport*t){if(!t)return;if(t->tls)cm_tls_close_polarssl(t->tls);free(t);}
